CREATE OR REPLACE FUNCTION digest.fb_link_content()
 RETURNS TABLE(posts_linked bigint, comments_linked bigint, images_enriched bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'digest', 'pg_temp'
AS $function$
declare p bigint; c bigint; ie bigint;
begin
  with ins as (
    insert into digest.content_items (source,kind,source_id,body,occurred_at,url,access_rule,sensitivity,meta)
    select 'fb_post','post',post_id,text,created_time,
      'https://www.facebook.com/groups/699138040189700/posts/'||post_id||'/',
      '{"type":"public"}'::jsonb,'normal',jsonb_build_object('author_name',author_name)
    from digest.fb_posts on conflict (source,source_id) do nothing returning 1)
  select count(*) into p from ins;
  with ins as (
    insert into digest.content_items (source,kind,source_id,body,occurred_at,url,access_rule,sensitivity,meta)
    select 'fb_comment','comment',fc.comment_id,fc.text,fc.created_time,
      'https://www.facebook.com/groups/699138040189700/posts/'||fc.post_id||'/',
      '{"type":"public"}'::jsonb,'normal',
      jsonb_build_object('post_id',fc.post_id,'author_name',fc.author_name,'sender_member',m.at_member_id)
    from digest.fb_comments fc left join digest.fb_member_map m on m.fb_uid=fc.author_uid
    on conflict (source,source_id) do nothing returning 1)
  select count(*) into c from ins;
  update digest.fb_post_images set storage_path = 'fb-images/' || regexp_replace(local_path, '^.*/', '')
   where storage_path is null and local_path is not null;
  with img as (
    select post_id, string_agg(nullif(trim(coalesce(description,'') ||
        case when nullif(ocr_text,'') is not null then ' [text in image: '||ocr_text||']' else '' end),''),' | ') as t
    from digest.fb_post_images where description is not null or nullif(ocr_text,'') is not null group by post_id),
  upd as (
    update digest.content_items ci set search_extra = img.t, embedding = null
    from img where ci.source='fb_post' and ci.source_id = img.post_id
      and img.t is not null and ci.search_extra is distinct from img.t returning 1)
  select count(*) into ie from upd;
  return query select p, c, ie;
end $function$
